// XS.Audio: the runtime (M6). One AudioContext for everything; buffers fetched lazily from XS.SOUNDS
// (data/sound-manifest.js, generated by tools/measure-audio.mjs); cue data from XS.AUDIO (data/audio-cues.js);
// log -> cue tags from XS.AudioMap (js/audio/map.js).
//
// Interface (M7 codes against exactly this):
//   XS.Audio.init()          -> true when audio is available, false (see .reason) when it is not
//   XS.Audio.unlock()        idempotent; installs session-long pointerup/touchend/click/keydown listeners that retry ctx.resume()
//   XS.Audio.onLog(entry, view)  play the cues of one log entry, at the moment the director SHOWS it
//   XS.Audio.cue(tag)        a UI sound (ui-hover, ui-click, ui-confirm, ui-cancel, ui-drawer)
//   XS.Audio.setScene(name)  'title'|'calm'|'tense'|'victory'|'defeat'|'silent'; ~1.2 s crossfade; victory/defeat play once
//   XS.Audio.settings        get/set {master, sfx, music, voice, muted}; 0..1; persistence is the interface's job (M7)
//   XS.Audio.coverage()      {cues, files, missing:[tags], ...}
//
// A cue without a file is a DECLARED pending state, not a fallback: it is reported once as `audio pending: <tag>`
// and listed by coverage(); nothing is synthesised in its place (CLAUDE.md rule 5). Without an AudioContext
// (node:vm tests, an old browser) init() returns false, `available` is false and every call is an explicit no-op.
// Rate limits: at most 6 concurrent SFX, a minimum gap per tag (60 ms), identical tags inside one tick (one
// director batch) play once, one announcer line at a time. Not verified by ear: tune on sounds.html.
(function () {
  'use strict';
  const XS = (globalThis.XS = globalThis.XS || {});

  // The environment XS.Audio runs in. Tests build a second instance over a fake one (XS.Audio._create).
  const defaultEnv = {
    get AudioContext() { return globalThis.AudioContext || globalThis.webkitAudioContext || null; },
    get document() { return typeof document === 'undefined' ? null : document; },
    get window() { return typeof window === 'undefined' ? null : window; },
    get navigator() { return typeof navigator === 'undefined' ? null : navigator; },
    fetch: (...a) => globalThis.fetch(...a),
    now: () => (typeof performance !== 'undefined' ? performance.now() : Date.now()),
    setTimeout: (...a) => setTimeout(...a),
    console,
  };

  function make(env) {
  const MAX_SFX = 6;
  const MIN_GAP_MS = 60;
  const GAP_OVERRIDE_MS = { 'ui-hover': 120, 'card-draw': 90, 'pp-spend': 90, 'pp-recover': 120 };
  const FADE_S = 1.2;                 // music crossfade
  const LATE_MS = 500;                // a first-time sound that decodes later than this after its moment is skipped
  const VOICE_MAX_WAIT_S = 3;         // an announcer line that would start later than this is stale
  const VOICE_DUCK = 0.55;            // music level under an announcer line
  const GESTURES = ['pointerup', 'touchend', 'click', 'keydown'];
  const SCENE_NAMES = ['title', 'calm', 'tense', 'victory', 'defeat', 'silent'];
  const ONCE = { victory: true, defeat: true };

  const A = {};

  let ctx = null, master = null, bus = null, duckNode = null;
  let initDone = false, available = false, reason = 'init() not called';
  let listenersOn = false, wasRunning = false;
  let cfg = { master: 0.8, sfx: 1, music: 0.7, voice: 1, muted: false };
  const buffers = {};                 // tag -> AudioBuffer
  const loading = {};                 // tag -> Promise<AudioBuffer|null>
  const warned = {};                  // tag / key -> true (console reports happen once)
  const lastAt = {};                  // tag -> performance.now() of its last start
  const ducks = new Map();            // id -> level
  let duckId = 0;
  let activeSfx = [];                 // [{src, gain, at}]
  let batch = null;                   // Set of tags played in the current tick
  let voiceFreeAt = 0;                // audio-clock time the announcer channel is free
  let want = null;                    // wanted scene (kept while locked)
  let cur = null;                     // {scene, tag, src, gain}
  const stats = { limited: 0, deduped: 0, late: 0, locked: 0, staleVoice: 0 };

  const cuesAll = () => { if (!XS.AUDIO || !XS.AUDIO.byTag) throw new Error('XS.Audio: data/audio-cues.js is not loaded'); return XS.AUDIO; };
  const mapAll = () => { if (!XS.AudioMap) throw new Error('XS.Audio: js/audio/map.js is not loaded'); return XS.AudioMap; };
  const soundsAll = () => { if (!XS.SOUNDS) throw new Error('XS.Audio: data/sound-manifest.js is not loaded'); return XS.SOUNDS; };
  const cueOf = (tag) => { const c = cuesAll().byTag[tag]; if (!c) throw new Error('XS.Audio: unknown cue "' + tag + '"'); return c; };
  const now = () => env.now();

  function pending(tag) {
    if (warned[tag]) return;
    warned[tag] = true;
    env.console.warn('audio pending: ' + tag);
  }

  // ---- context ------------------------------------------------------------------------------------------------
  A.init = function () {
    cuesAll(); mapAll(); soundsAll();                       // missing modules throw (a broken build, not a quiet game)
    if (initDone) return available;
    initDone = true;
    const AC = env.AudioContext;
    if (!AC) {
      reason = 'no AudioContext in this environment';
      if (env.document) env.console.warn('audio unavailable: ' + reason);
      return false;
    }
    ctx = new AC({ latencyHint: 'interactive' });
    master = ctx.createGain();
    duckNode = ctx.createGain();
    bus = { sfx: ctx.createGain(), music: ctx.createGain(), voice: ctx.createGain() };
    bus.sfx.connect(master); bus.voice.connect(master);
    bus.music.connect(duckNode); duckNode.connect(master);
    master.connect(ctx.destination);
    applySettings();
    ctx.onstatechange = onState;
    // iOS 17+: play through the silent switch (a media session, not an ambient one).
    try { if (env.navigator && env.navigator.audioSession) env.navigator.audioSession.type = 'playback'; } catch (e) { /* read-only on some builds */ }
    available = true; reason = '';
    installListeners();
    onState();
    return true;
  };

  Object.defineProperty(A, 'available', { get: () => available, enumerable: true });
  Object.defineProperty(A, 'reason', { get: () => reason, enumerable: true });

  function onState() {
    if (!ctx) return;
    const running = ctx.state === 'running';
    if (running && !wasRunning) { wasRunning = true; afterRunning(); }
    else if (!running) { wasRunning = false; resume(); }
  }
  function resume() {
    if (!ctx || ctx.state === 'running' || ctx.state === 'closed') return;
    try { const p = ctx.resume(); if (p && p.catch) p.catch(() => { /* retried on the next gesture */ }); } catch (e) { /* retried on the next gesture */ }
  }
  function prime() {                                         // a silent buffer started inside the gesture unlocks iOS
    try {
      const s = ctx.createBufferSource();
      s.buffer = ctx.createBuffer(1, 1, ctx.sampleRate);
      s.connect(ctx.destination);
      s.start(0);
    } catch (e) { /* context torn down */ }
  }
  function onGesture() { if (!ctx) return; if (ctx.state !== 'running') prime(); resume(); }
  function installListeners() {
    const doc = env.document;
    if (listenersOn || !doc) return;
    listenersOn = true;
    for (const ev of GESTURES) doc.addEventListener(ev, onGesture, { capture: true, passive: true });   // kept for the whole session: a call or an app switch suspends the context again
    doc.addEventListener('visibilitychange', () => { if (!doc.hidden) resume(); });
    if (env.window) { env.window.addEventListener('pageshow', resume); env.window.addEventListener('focus', resume); }
  }
  A.unlock = function () {
    if (!initDone) A.init();
    if (!available) return false;
    installListeners();
    onGesture();
    return ctx.state === 'running';
  };
  function afterRunning() {
    if (want) applyScene(want);
    prewarm();
  }

  // ---- settings -----------------------------------------------------------------------------------------------
  function applySettings() {
    if (!ctx) return;
    const t = ctx.currentTime;
    master.gain.setTargetAtTime(cfg.muted ? 0 : cfg.master, t, 0.03);
    for (const k of ['sfx', 'music', 'voice']) bus[k].gain.setTargetAtTime(cfg[k], t, 0.03);
  }
  Object.defineProperty(A, 'settings', {
    enumerable: true,
    get: () => Object.assign({}, cfg),
    set(v) {
      if (!v || typeof v !== 'object') throw new Error('XS.Audio.settings: expected an object');
      const next = Object.assign({}, cfg);
      for (const [k, val] of Object.entries(v)) {
        if (k === 'muted') { if (typeof val !== 'boolean') throw new Error('XS.Audio.settings.muted must be a boolean'); next.muted = val; }
        else if (k === 'master' || k === 'sfx' || k === 'music' || k === 'voice') {
          if (typeof val !== 'number' || !(val >= 0 && val <= 1)) throw new Error('XS.Audio.settings.' + k + ' must be a number in 0..1');
          next[k] = val;
        } else throw new Error('XS.Audio.settings: unknown key "' + k + '"');
      }
      cfg = next;
      applySettings();
    },
  });

  // ---- buffers ------------------------------------------------------------------------------------------------
  function fileOf(tag) {
    const e = soundsAll()[tag];
    if (!e) return null;
    if (typeof e.file !== 'string' || typeof e.gain !== 'number') throw new Error('XS.SOUNDS["' + tag + '"] needs {file, seconds, gain}');
    return e;
  }
  function decode(ab) {
    return new Promise((resolve, reject) => {
      const p = ctx.decodeAudioData(ab, resolve, reject);     // callback form for older Safari, promise form elsewhere
      if (p && p.then) p.then(resolve, reject);
    });
  }
  function load(tag) {
    if (buffers[tag]) return Promise.resolve(buffers[tag]);
    const e = fileOf(tag);
    if (!e) { pending(tag); return Promise.resolve(null); }
    if (!loading[tag]) {
      loading[tag] = env.fetch(e.file)
        .then((r) => { if (!r.ok) throw new Error(e.file + ' ' + r.status); return r.arrayBuffer(); })
        .then(decode)
        .then((b) => { buffers[tag] = b; return b; })
        .catch((err) => { env.console.warn('audio load failed: ' + tag + ' (' + err.message + ')'); return null; });
    }
    return loading[tag];
  }
  function prewarm() {                                        // sfx and voice, one at a time, so the first hit is not late
    const tags = cuesAll().cues.filter((c) => c.kind !== 'music' && XS.SOUNDS[c.tag]).map((c) => c.tag);
    let i = 0;
    const next = () => { if (i < tags.length) load(tags[i++]).then(() => env.setTimeout(next, 0)); };
    next();
  }

  // ---- ducking ------------------------------------------------------------------------------------------------
  function duck(level, seconds) {
    if (!ctx) return;
    const id = ++duckId;
    ducks.set(id, level);
    applyDuck();
    env.setTimeout(() => { ducks.delete(id); applyDuck(); }, Math.max(0.1, seconds) * 1000);
  }
  function applyDuck() {
    let m = 1;
    for (const v of ducks.values()) m = Math.min(m, v);
    duckNode.gain.setTargetAtTime(m, ctx.currentTime, 0.05);
  }

  // ---- sfx and voice ------------------------------------------------------------------------------------------
  function startSfx(cue, buf, delay) {
    const t = ctx.currentTime + (delay || 0);
    activeSfx = activeSfx.filter((a) => a.end > ctx.currentTime);
    if (activeSfx.length >= MAX_SFX) {
      const oldest = activeSfx[0];
      if (cue.gain >= oldest.gain) { try { oldest.src.stop(); } catch (e) { /* already ended */ } activeSfx.shift(); }
      else { stats.limited++; return false; }
    }
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const g = ctx.createGain();
    g.gain.value = fileOf(cue.tag).gain;
    src.connect(g); g.connect(bus.sfx);
    src.start(t);
    activeSfx.push({ src, gain: cue.gain, end: t + buf.duration });
    if (cue.duck) duck(cue.duck, buf.duration + (delay || 0));
    return true;
  }
  function startVoice(cue, buf, delay) {
    const at = Math.max(ctx.currentTime + (delay || 0), voiceFreeAt);
    if (at - ctx.currentTime > VOICE_MAX_WAIT_S) { stats.staleVoice++; return false; }
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const g = ctx.createGain();
    g.gain.value = fileOf(cue.tag).gain;
    src.connect(g); g.connect(bus.voice);
    src.start(at);
    voiceFreeAt = at + buf.duration + 0.15;
    env.setTimeout(() => duck(VOICE_DUCK, buf.duration + 0.2), Math.max(0, (at - ctx.currentTime) * 1000));
    return true;
  }

  // Play one non-music cue now. Returns true when a sound was started or queued on the audio clock.
  function playCue(tag) {
    const cue = cueOf(tag);
    if (cue.kind === 'music') { const scene = Object.keys(mapAll().SCENES).find((k) => mapAll().SCENES[k] === tag); A.setScene(scene); return true; }
    if (!available) return false;
    if (!batch) { batch = new Set(); Promise.resolve().then(() => { batch = null; }); }
    if (batch.has(tag)) { stats.deduped++; return false; }
    batch.add(tag);
    const t = now();
    if (lastAt[tag] !== undefined && t - lastAt[tag] < (GAP_OVERRIDE_MS[tag] || MIN_GAP_MS)) { stats.limited++; return false; }
    lastAt[tag] = t;
    if (!fileOf(tag)) { pending(tag); return false; }
    if (ctx.state !== 'running') { stats.locked++; resume(); return false; }   // a sound played after unlock would be stale
    const go = (buf) => (cue.kind === 'voice' ? startVoice(cue, buf, cue.delay) : startSfx(cue, buf, cue.delay));
    if (buffers[tag]) return go(buffers[tag]);
    const asked = now();
    load(tag).then((buf) => { if (buf && now() - asked <= LATE_MS) go(buf); else if (buf) stats.late++; });
    return true;
  }

  A.cue = function (tag) {
    cueOf(tag);
    return playCue(tag);
  };

  A.onLog = function (entry, view) {
    const M = mapAll();
    if (!M.has(entry.type)) {
      if (!warned['type:' + entry.type]) { warned['type:' + entry.type] = true; env.console.warn('audio map: unmapped log type "' + entry.type + '"'); }
      return false;
    }
    let any = false;
    for (const tag of M.cuesFor(entry, view)) any = playCue(tag) || any;
    return any;
  };

  // ---- music --------------------------------------------------------------------------------------------------
  A.setScene = function (name) {
    if (!SCENE_NAMES.includes(name)) throw new Error('XS.Audio.setScene: unknown scene "' + name + '"');
    cuesAll();
    if (want === name && (!available || cur)) return;
    want = name;
    if (!available || !ctx || ctx.state !== 'running') return;    // kept; started by afterRunning() once the context runs
    applyScene(name);
  };
  function fadeOut(c, secs) {
    if (!c) return;
    const t = ctx.currentTime;
    try {
      c.gain.gain.cancelScheduledValues(t);
      c.gain.gain.setValueAtTime(c.gain.gain.value, t);
      c.gain.gain.linearRampToValueAtTime(0.0001, t + secs);
      c.src.stop(t + secs + 0.05);
    } catch (e) { /* already stopped */ }
  }
  function applyScene(name) {
    const tag = mapAll().SCENES[name];
    if (cur && cur.scene === name) return;
    if (tag === null) { fadeOut(cur, FADE_S); cur = null; return; }
    const cue = cueOf(tag);
    if (!fileOf(tag)) { pending(tag); fadeOut(cur, FADE_S); cur = null; return; }   // pending: silence, declared
    load(tag).then((buf) => {
      if (!buf || want !== name || !ctx || (cur && cur.scene === name)) return;
      const t = ctx.currentTime;
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.loop = !!cue.loop && !ONCE[name];
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(fileOf(tag).gain, t + FADE_S);
      src.connect(g); g.connect(bus.music);
      src.start(t);
      fadeOut(cur, FADE_S);
      cur = { scene: name, tag, src, gain: g };
    });
  }

  // ---- reporting ----------------------------------------------------------------------------------------------
  A.coverage = function () {
    const S = soundsAll(), cues = cuesAll().cues;
    const missing = cues.filter((c) => !S[c.tag]).map((c) => c.tag);
    const orphans = Object.keys(S).filter((k) => !cuesAll().byTag[k]);
    return { cues: cues.length, files: cues.length - missing.length, missing, orphans };
  };
  A._buffers = buffers;                       // test hooks: tests seed decoded buffers and end a batch by hand
  A._flushBatch = () => { batch = null; };
  A._debug = () => ({ available, reason, state: ctx ? ctx.state : 'none', scene: cur ? cur.scene : null, want, active: activeSfx.length, stats: Object.assign({}, stats) });
  return A;
  }

  XS.Audio = make(defaultEnv);
  XS.Audio._create = make;                    // test hook: a second instance over a fake environment
})();
